DEFAULT_POLICY = {"version": 1, "publish_threshold": 70,
    "bands": {"warning": 40, "good": 70},
    "weights": {"authorized": 35, "twofa": 30, "recovery": 20, "sessions": 15}}


def now() -> int:
    return int(time.time())


def uid() -> str:
    return uuid.uuid4().hex


def digest(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()


def rub(amount: int) -> str:
    return format(Decimal(amount) / 100, ".2f")


def money_input(value: Any, *, allow_zero: bool = False) -> int:
    text = str(value).strip().replace(" ", "").replace("₽", "").replace(",", ".")
    if not re.fullmatch(r"\d{1,9}(?:\.\d{1,2})?", text):
        raise Fault("Укажите сумму в рублях, не больше двух знаков после запятой")
    result = int(Decimal(text) * 100)
    if result < (0 if allow_zero else 1) or result > 100_000_000:
        raise Fault("Сумма должна быть от 0,01 до 1 000 000 ₽")
    return result


def ltc_amount(kopeks: int, rate: Decimal) -> str:
    if not rate.is_finite() or rate <= 0:
        raise Fault("Источник вернул некорректный курс", 503)
    amount = (Decimal(kopeks) / 100 / rate).quantize(Decimal("0.00000001"), rounding=ROUND_CEILING)
    return format(amount, ".8f")


def validate_address(address: str) -> bool:
    try:
        hrp, data = address.rsplit("1", 1)
        if hrp != "ltc" or address != address.lower():
            return False
        charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
        values = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp] + [charset.index(c) for c in data]
        check = 1
        for value in values:
            top = check >> 25
            check = ((check & 0x1ffffff) << 5) ^ value
            for i, generator in enumerate((0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3)):
                if top >> i & 1:
                    check ^= generator
        return check == 1 and data[0] == "q" and len(data) in (39, 59)
    except (ValueError, IndexError):
        return False


class Fault(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


def load_env(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text("utf-8").splitlines():
        if not line.strip() or line.lstrip().startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        if re.fullmatch(r"[A-Z][A-Z0-9_]*", key.strip()):
            os.environ.setdefault(key.strip(), value.strip().strip('"').strip("'"))


@dataclass
class Settings:
    data_dir: Path
    bot_token: str = ""
    public_url: str = ""
    api_id: int = 0
    api_hash: str = ""
    demo: bool = False
    admin_key: str = ""
    admin_ids: tuple[int, ...] = ()
    session_ttl: int = 86400
    quote_ttl: int = 900
    code_wait: int = 90
    code_max_age: int = 180
    code_ttl: int = 120
    lease_seconds: int = 120
    worker_concurrency: int = 4
    cg_key: str = ""
    webhook_secret: str = ""
    webhook_url: str = ""
    bot_username: str = ""

    @classmethod
    def from_env(cls, args: argparse.Namespace) -> "Settings":
        directory = Path(os.environ.get("DATA_DIR", str(Path(__file__).resolve().parent / "acczlol_data")))
        load_env(Path(__file__).resolve().with_name("acczlol.env"))
        directory = Path(os.environ.get("DATA_DIR", str(directory)))
        ids = tuple(int(x.strip()) for x in os.environ.get("ADMIN_IDS", "").split(",") if x.strip())
        if args.demo:
            directory = directory / "demo"
        return cls(directory, os.environ.get("BOT_TOKEN", ""), os.environ.get("PUBLIC_URL", "").rstrip("/"),
            int(os.environ.get("TELEGRAM_API_ID", "0") or 0), os.environ.get("TELEGRAM_API_HASH", ""), args.demo,
            os.environ.get("ADMIN_KEY", ""), ids, worker_concurrency=int(os.environ.get("AGENT_CONCURRENCY", "4")),
            cg_key=os.environ.get("COINGECKO_API_KEY", ""), webhook_secret=os.environ.get("WEBHOOK_SECRET", ""),
            webhook_url=os.environ.get("WEBHOOK_URL", ""), bot_username=os.environ.get("BOT_USERNAME", ""))


class Vault:
    def __init__(self, directory: Path, explicit_key: str = ""):
        directory.mkdir(parents=True, exist_ok=True)
        with contextlib.suppress(OSError):
            directory.chmod(0o700)
        key_path = directory / "vault.key"
        if explicit_key:
            key = explicit_key.encode()
        elif key_path.exists():
            key = key_path.read_bytes().strip()
        else:
            key = Fernet.generate_key()
            try:
                fd = os.open(key_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
                with os.fdopen(fd, "wb") as f:
                    f.write(key)
            except FileExistsError:
                key = key_path.read_bytes().strip()
        self.fernet = Fernet(key)

    def seal(self, value: Any) -> str:
        return self.fernet.encrypt(json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()).decode()

    def open(self, value: str) -> Any:
        try:
            return json.loads(self.fernet.decrypt(value.encode()))
        except (InvalidToken, ValueError, TypeError):
            raise Fault("Не удалось расшифровать данные. Проверьте ключ хранилища", 503) from None


SCHEMA = """
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,username TEXT NOT NULL DEFAULT '',balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),admin_until INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS web_sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_codes(code_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,telegram_id INTEGER UNIQUE,title TEXT NOT NULL,username TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>0),kind TEXT NOT NULL DEFAULT 'new',state TEXT NOT NULL DEFAULT 'draft',score INTEGER,security_json TEXT NOT NULL DEFAULT '{}',secret_enc TEXT NOT NULL,login_enc TEXT NOT NULL DEFAULT '',cover TEXT NOT NULL DEFAULT 'hero',last_code_message_id INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,checked_at INTEGER);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),account_id TEXT NOT NULL REFERENCES accounts(id),amount INTEGER NOT NULL,state TEXT NOT NULL,request_key TEXT NOT NULL,created_at INTEGER NOT NULL,completed_at INTEGER,error_code TEXT NOT NULL DEFAULT '',UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),delta INTEGER NOT NULL,kind TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,reference TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS topups(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),rub_kopeks INTEGER NOT NULL,ltc_amount TEXT NOT NULL,rate TEXT NOT NULL,source TEXT NOT NULL,address TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'awaiting',txid TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,submitted_at INTEGER,reviewed_at INTEGER,reviewed_by INTEGER,note TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS unique_topup_txid ON topups(txid) WHERE txid<>'';
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),state TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS support_messages(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL REFERENCES tickets(id),actor TEXT NOT NULL,body_enc TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,account_id TEXT NOT NULL,order_id TEXT,user_id INTEGER,payload_enc TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'waiting',stage TEXT NOT NULL DEFAULT 'Ожидание',worker_id TEXT NOT NULL DEFAULT '',lease_until INTEGER NOT NULL DEFAULT 0,retry_at INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,error_code TEXT NOT NULL DEFAULT '',result_enc TEXT NOT NULL DEFAULT '',result_expires INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_job ON jobs(account_id) WHERE state IN ('waiting','checking');
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,reference TEXT NOT NULL DEFAULT '',result TEXT NOT NULL DEFAULT 'ok',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bot_states(user_id INTEGER PRIMARY KEY,state TEXT NOT NULL,payload_enc TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,payload_enc TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'waiting',attempts INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,due_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS processed_updates(id INTEGER PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS orders_owner ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(state,retry_at,created_at);
"""


class Store:
    def __init__(self, path: Path, vault: Vault, settings: Settings):
        self.path, self.vault, self.settings = path, vault, settings
        with self.connect() as db:
            db.executescript(SCHEMA)
            db.execute("INSERT OR IGNORE INTO settings VALUES('security',?)", (json.dumps(DEFAULT_POLICY),))
        with contextlib.suppress(OSError):
            path.chmod(0o600)

    @contextlib.contextmanager
    def connect(self):
        db = sqlite3.connect(self.path, timeout=20, isolation_level=None)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys=ON")
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA busy_timeout=20000")
        try:
            yield db
        finally:
            db.close()

    @contextlib.contextmanager
    def transaction(self):
        with self.connect() as db:
            db.execute("BEGIN IMMEDIATE")
            try:
                yield db
                db.commit()
            except BaseException:
                db.rollback()
                raise

    def query(self, sql: str, values: tuple = ()) -> list[dict]:
        with self.connect() as db:
            return [dict(r) for r in db.execute(sql, values).fetchall()]

    def one(self, sql: str, values: tuple = ()) -> dict | None:
        rows = self.query(sql, values)
        return rows[0] if rows else None

    def execute(self, sql: str, values: tuple = ()) -> int:
        with self.connect() as db:
            return db.execute(sql, values).rowcount

    @staticmethod
    def audit(db: sqlite3.Connection, actor: Any, action: str, reference: str = "", result: str = "ok") -> None:
        db.execute("INSERT INTO audit(actor,action,reference,result,created_at) VALUES(?,?,?,?,?)", (str(actor), action, reference, result, now()))

    def user(self, telegram_user: dict) -> dict:
        user_id = int(telegram_user["id"])
        if user_id <= 0:
            raise Fault("Некорректный пользователь", 401)
        name = str(telegram_user.get("first_name") or telegram_user.get("name") or "Покупатель")[:100]
        username = str(telegram_user.get("username", ""))[:64]
        with self.transaction() as db:
            db.execute("INSERT INTO users(id,name,username,created_at) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,username=excluded.username", (user_id, name, username, now()))
            if user_id in self.settings.admin_ids:
                db.execute("UPDATE users SET admin_until=? WHERE id=?", (now()+86400, user_id))
            return dict(db.execute("SELECT * FROM users WHERE id=?", (user_id,)).fetchone())

    def make_session(self, user_id: int) -> str:
        raw = secrets.token_urlsafe(40)
        self.execute("INSERT INTO web_sessions VALUES(?,?,?)", (digest(raw), user_id, now()+self.settings.session_ttl))
        return raw

    def session_user(self, raw: str) -> dict | None:
        return self.one("SELECT u.* FROM web_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>?", (digest(raw), now())) if raw else None

    def unlock_admin(self, user_id: int, key: str) -> None:
        if self.settings.admin_ids and user_id not in self.settings.admin_ids:
            raise Fault("Для этого Telegram ID административный вход отключён", 403)
        if self.settings.admin_key:
            valid = hmac.compare_digest(key.encode(), self.settings.admin_key.encode())
        else:
            actual = hashlib.pbkdf2_hmac("sha256", key.encode(), base64.b64decode(DEFAULT_ADMIN_SALT), PBKDF_ROUNDS).hex()
            valid = hmac.compare_digest(actual, DEFAULT_ADMIN_DIGEST)
        if not valid:
            raise Fault("Неверный админ-ключ", 403)
        with self.transaction() as db:
            db.execute("UPDATE users SET admin_until=? WHERE id=?", (now()+43200, user_id))
            self.audit(db, user_id, "Вход в админ-панель")

    def admin_ids(self) -> list[int]:
        return list(set(self.settings.admin_ids) | {r["id"] for r in self.query("SELECT id FROM users WHERE admin_until>?", (now(),))})

    def app_login_code(self, user_id: int) -> str:
        code = "".join(secrets.choice("0123456789") for _ in range(12))
        with self.transaction() as db:
            db.execute("DELETE FROM login_codes WHERE user_id=? OR expires_at<?", (user_id, now()))
            db.execute("INSERT INTO login_codes(code_hash,user_id,expires_at) VALUES(?,?,?)", (digest(code), user_id, now()+180))
        return code

    def redeem_login_code(self, code: str) -> str:
        clean = re.sub(r"[ -]", "", str(code))
        if not re.fullmatch(r"\d{12}", clean):
            raise Fault("Код входа в acczLOL содержит 12 цифр", 401)
        with self.transaction() as db:
            row = db.execute("SELECT * FROM login_codes WHERE code_hash=? AND expires_at>? AND used=0", (digest(clean), now())).fetchone()
            if not row:
                raise Fault("Код недействителен или истёк. Получите новый командой /login в боте", 401)
            db.execute("UPDATE login_codes SET used=1 WHERE code_hash=?", (digest(clean),))
            raw = secrets.token_urlsafe(40)
            db.execute("INSERT INTO web_sessions VALUES(?,?,?)", (digest(raw), row["user_id"], now()+self.settings.session_ttl))
            return raw

    def set_bot_state(self, user_id: int, state: str, payload: dict | None = None) -> None:
        self.execute("INSERT INTO bot_states VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET state=excluded.state,payload_enc=excluded.payload_enc,expires_at=excluded.expires_at", (user_id, state, self.vault.seal(payload or {}), now()+900))

    def bot_state(self, user_id: int) -> tuple[str, dict]:
        row = self.one("SELECT * FROM bot_states WHERE user_id=? AND expires_at>?", (user_id, now()))
        return (row["state"], self.vault.open(row["payload_enc"])) if row else ("", {})

    def clear_bot_state(self, user_id: int) -> None:
        self.execute("DELETE FROM bot_states WHERE user_id=?", (user_id,))

    def enqueue_outbox(self, payload: dict, event_id: str | None = None, due_at: int | None = None) -> None:
        with self.connect() as db:
            self._enqueue(db, payload, event_id, due_at)

    def _enqueue(self, db: sqlite3.Connection, payload: dict, event_id: str | None = None, due_at: int | None = None) -> None:
        db.execute("INSERT OR IGNORE INTO outbox(id,payload_enc,due_at,created_at) VALUES(?,?,?,?)", (event_id or uid(), self.vault.seal(payload), due_at or now(), now()))

    def notify_admins(self, text: str, keyboard: dict | None = None, event: str = "") -> None:
        for admin_id in self.admin_ids():
            self.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": admin_id, "text": text, "parse_mode": "HTML", **({"reply_markup": keyboard} if keyboard else {})}}, f"{event}:{admin_id}" if event else None)

    def policy(self) -> dict:
        return json.loads(self.one("SELECT value FROM settings WHERE key='security'")["value"])

    def save_policy(self, actor: int, supplied: dict) -> dict:
        old = self.policy()
        try:
            threshold = int(supplied["publish_threshold"])
            weights = {key: int(supplied["weights"][key]) for key in old["weights"]}
        except (KeyError, TypeError, ValueError):
            raise Fault("Проверьте веса и порог") from None
        if not 0 <= threshold <= 100 or any(not 1 <= v <= 1000 for v in weights.values()):
            raise Fault("Порог 0–100, веса 1–1000")
        policy = {**old, "version": old["version"]+1, "publish_threshold": threshold, "weights": weights}
        with self.transaction() as db:
            db.execute("UPDATE settings SET value=? WHERE key='security'", (json.dumps(policy),))
            self.audit(db, actor, "Обновлены веса безопасности", str(policy["version"]))
        return policy

    def catalog(self, minimum: int = 0, maximum: int = 100_000_000, search: str = "") -> list[dict]:
        rows = self.query("SELECT id,title,username,price,kind,score,security_json,cover,checked_at FROM accounts WHERE state='available' AND price BETWEEN ? AND ? ORDER BY price,id", (minimum, maximum))
        if search:
            rows = [r for r in rows if search.casefold() in (r["title"]+" "+r["username"]).casefold()]
        for row in rows:
            row["price_rub"] = rub(row["price"])
            row["security"] = json.loads(row.pop("security_json"))
        return rows

    @staticmethod
    def _job(db: sqlite3.Connection, vault: Vault, kind: str, account_id: str, order_id: str | None = None, user_id: int | None = None, payload: dict | None = None) -> str:
        job_id = uid()
        db.execute("INSERT INTO jobs(id,kind,account_id,order_id,user_id,payload_enc,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)", (job_id, kind, account_id, order_id, user_id, vault.seal(payload or {}), now(), now()))
        return job_id

    def add_account(self, actor: int, title: str, price: int, session: str, password: str, kind: str) -> str:
        if not session or len(session) > 20000 or len(password) > 256:
            raise Fault("Проверьте формат сессии и пароля")
        account_id = uid()
        with self.transaction() as db:
            db.execute("INSERT INTO accounts(id,title,price,kind,secret_enc,created_at) VALUES(?,?,?,?,?,?)", (account_id, title[:100] or "Telegram аккаунт", price, "warmed" if kind == "warmed" else "new", self.vault.seal({"session": session, "password": password}), now()))
            self._job(db, self.vault, "validate", account_id)
            self.audit(db, actor, "Импорт сессии аккаунта", account_id)
        return account_id

    def recheck(self, actor: int, account_id: str) -> str:
        with self.transaction() as db:
            a = db.execute("SELECT state FROM accounts WHERE id=?", (account_id,)).fetchone()
            if not a:
                raise Fault("Аккаунт не найден", 404)
            if a["state"] in ("sold", "reserved"):
                raise Fault("Аккаунт уже участвует в сделке", 409)
            if db.execute("SELECT 1 FROM orders WHERE account_id=? AND completed_at IS NOT NULL", (account_id,)).fetchone():
                raise Fault("Аккаунт ранее выдан покупателю. Автоматическое возвращение в сток отключено", 409)
            try:
                job_id = self._job(db, self.vault, "validate", account_id)
            except sqlite3.IntegrityError:
                raise Fault("Проверка уже в очереди", 409) from None
            db.execute("UPDATE accounts SET state='checking' WHERE id=?", (account_id,))
            self.audit(db, actor, "Повторная проверка", account_id)
            return job_id

    def buy(self, user_id: int, account_id: str, request_key: str) -> dict:
        if not re.fullmatch(r"[a-zA-Z0-9:_-]{8,128}", request_key):
            raise Fault("Некорректный идентификатор покупки")
        with self.transaction() as db:
            previous = db.execute("SELECT * FROM orders WHERE user_id=? AND request_key=?", (user_id, request_key)).fetchone()
            if previous:
                if previous["account_id"] != account_id:
                    raise Fault("Идентификатор уже использован для другой покупки", 409)
                return dict(previous)
            account = db.execute("SELECT * FROM accounts WHERE id=?", (account_id,)).fetchone()
            if not account or account["state"] != "available":
                raise Fault("Аккаунт уже куплен или недоступен", 409)
            balance = db.execute("SELECT balance FROM users WHERE id=?", (user_id,)).fetchone()
            if not balance or balance["balance"] < account["price"]:
                raise Fault("Недостаточно средств на балансе", 409)
            order_id = uid()
            db.execute("UPDATE users SET balance=balance-? WHERE id=?", (account["price"], user_id))
            db.execute("UPDATE accounts SET state='reserved' WHERE id=?", (account_id,))
            db.execute("INSERT INTO orders(id,user_id,account_id,amount,state,request_key,created_at) VALUES(?,?,?,?,'checking',?,?)", (order_id, user_id, account_id, account["price"], request_key, now()))
            db.execute("INSERT INTO ledger(user_id,delta,kind,event_key,reference,created_at) VALUES(?,?,'purchase',?,?,?)", (user_id, -account["price"], "purchase:"+order_id, order_id, now()))
            self._job(db, self.vault, "fulfill", account_id, order_id, user_id)
            self.audit(db, user_id, "Покупка: резерв и списание баланса", order_id)
            return dict(db.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone())

    def order_rows(self, user_id: int | None = None) -> list[dict]:
        sql = "SELECT o.*,a.title,a.username,a.cover,a.score,a.login_enc,u.name,u.username buyer_username,j.state agent_state,j.stage agent_stage FROM orders o JOIN accounts a ON a.id=o.account_id JOIN users u ON u.id=o.user_id LEFT JOIN jobs j ON j.id=(SELECT id FROM jobs WHERE order_id=o.id AND kind='fulfill' ORDER BY created_at DESC LIMIT 1)"
        values = ()
        if user_id is not None:
            sql += " WHERE o.user_id=?"
            values = (user_id,)
        rows = self.query(sql+" ORDER BY o.created_at DESC,o.id", values)
        for row in rows:
            login_enc = row.pop("login_enc")
            row["login"] = self.vault.open(login_enc).get("login", "") if login_enc and row["state"] == "complete" else ""
            row["amount_rub"] = rub(row["amount"])
        return rows

    def access(self, user_id: int, order_id: str, admin: bool = False) -> dict:
        row = self.one("SELECT o.*,a.secret_enc,a.login_enc FROM orders o JOIN accounts a ON a.id=o.account_id WHERE o.id=?", (order_id,))
        if not row or (row["user_id"] != user_id and not admin):
            raise Fault("Нет доступа к заказу", 403)
        if row["state"] != "complete":
            raise Fault("Выдача ещё не завершена или заказ возвращён", 409)
        secret = self.vault.open(row["secret_enc"])
        login = self.vault.open(row["login_enc"])
        with self.transaction() as db:
            self.audit(db, user_id, "Просмотр логина и 2FA", order_id)
        return {"login": login.get("login", ""), "password": secret.get("password", "") if secret.get("password_active", True) else "", "ttl": 60}

    def request_code(self, user_id: int, order_id: str, origin: str = "web") -> str:
        with self.transaction() as db:
            order = db.execute("SELECT * FROM orders WHERE id=? AND user_id=?", (order_id, user_id)).fetchone()
            if not order:
                raise Fault("Нет доступа к заказу", 403)
            if order["state"] != "complete":
                raise Fault("Код доступен только владельцу завершённой покупки", 409)
            active = db.execute("SELECT id,kind,user_id FROM jobs WHERE account_id=? AND state IN ('waiting','checking')", (order["account_id"],)).fetchone()
            if active:
                if active["kind"] == "code" and active["user_id"] == user_id:
                    if origin == "bot":
                        row = db.execute("SELECT payload_enc FROM jobs WHERE id=?", (active["id"],)).fetchone()
                        payload = self.vault.open(row["payload_enc"])
                        payload["origin"] = "bot"
                        db.execute("UPDATE jobs SET payload_enc=? WHERE id=?", (self.vault.seal(payload), active["id"]))
                    return active["id"]
                raise Fault("Для аккаунта уже выполняется операция", 409)
            recent = db.execute("SELECT id FROM jobs WHERE account_id=? AND kind='code' AND state='ready' AND result_expires>? AND user_id=? ORDER BY created_at DESC LIMIT 1", (order["account_id"], now(), user_id)).fetchone()
            if recent:
                return recent["id"]
            job_id = self._job(db, self.vault, "code", order["account_id"], order_id, user_id, {"origin": origin})
            self.audit(db, user_id, "Запрошен свежий код входа", order_id)
            return job_id

    def job_result(self, user_id: int, job_id: str, admin: bool = False) -> dict:
        row = self.one("SELECT * FROM jobs WHERE id=?", (job_id,))
        if not row or (row["user_id"] != user_id and not admin):
            raise Fault("Задача не найдена", 404)
        data = {key: row[key] for key in ("id", "kind", "state", "stage", "error_code", "updated_at")}
        if row["kind"] == "code" and row["state"] == "ready":
            if row["user_id"] != user_id:
                raise Fault("Код предназначен только покупателю", 403)
            if row["result_expires"] <= now():
                raise Fault("Срок показа кода истёк. Запросите новый", 410)
            order = self.one("SELECT state FROM orders WHERE id=? AND user_id=?", (row["order_id"], user_id))
            if not order or order["state"] != "complete":
                raise Fault("Доступ к заказу закрыт", 403)
            data.update(self.vault.open(row["result_enc"]))
            data["expires_at"] = row["result_expires"]
            data["expires_in"] = max(0, row["result_expires"]-now())
        return data

    def create_topup(self, user_id: int, amount: int, rate: Decimal, source: str) -> dict:
        invoice_id, stamp = uid(), now()
        if amount <= 0:
            raise Fault("Сумма должна быть положительной")
        amount_ltc = ltc_amount(amount, rate)
        with self.transaction() as db:
            pending = db.execute("SELECT COUNT(*) FROM topups WHERE user_id=? AND state IN ('awaiting','submitted') AND created_at>?", (user_id, now()-86400)).fetchone()[0]
            if pending >= 10:
                raise Fault("Слишком много открытых заявок. Обратитесь в поддержку", 429)
            db.execute("INSERT INTO topups(id,user_id,rub_kopeks,ltc_amount,rate,source,address,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?,?)", (invoice_id, user_id, amount, amount_ltc, str(rate), source, LTC_ADDRESS, stamp, stamp+self.settings.quote_ttl))
        return self.one("SELECT * FROM topups WHERE id=?", (invoice_id,))

    def submit_topup(self, user_id: int, invoice_id: str, txid: str) -> dict:
        txid = txid.strip().lower()
        if not re.fullmatch(r"[a-f0-9]{64}", txid):
            raise Fault("Укажите TXID из 64 шестнадцатеричных символов")
        with self.transaction() as db:
            row = db.execute("SELECT * FROM topups WHERE id=? AND user_id=?", (invoice_id, user_id)).fetchone()
            if not row:
                raise Fault("Заявка не найдена", 404)
            if row["state"] in ("approved", "rejected"):
                raise Fault("Заявка уже рассмотрена", 409)
            if row["state"] == "submitted":
                if row["txid"] != txid:
                    raise Fault("Для заявки уже указан другой TXID", 409)
                return dict(row)
            try:
                db.execute("UPDATE topups SET state='submitted',txid=?,submitted_at=? WHERE id=?", (txid, now(), invoice_id))
            except sqlite3.IntegrityError:
                raise Fault("Этот TXID уже используется в другой заявке", 409) from None
            self.audit(db, user_id, "Пополнение ожидает ручного подтверждения", invoice_id)
            return dict(db.execute("SELECT * FROM topups WHERE id=?", (invoice_id,)).fetchone())

    def review_topup(self, actor: int, invoice_id: str, approve: bool, note: str = "") -> dict:
        with self.transaction() as db:
            row = db.execute("SELECT * FROM topups WHERE id=?", (invoice_id,)).fetchone()
            if not row:
                raise Fault("Заявка не найдена", 404)
            target = "approved" if approve else "rejected"
            if row["state"] == target:
                return dict(row)
            if row["state"] != "submitted":
                raise Fault("Ожидается заявка с TXID; рассмотренную заявку нельзя изменить", 409)
            if approve:
                db.execute("INSERT INTO ledger(user_id,delta,kind,event_key,reference,created_at) VALUES(?,?,'topup',?,?,?)", (row["user_id"], row["rub_kopeks"], "topup:"+invoice_id, invoice_id, now()))
                db.execute("UPDATE users SET balance=balance+? WHERE id=?", (row["rub_kopeks"], row["user_id"]))
            db.execute("UPDATE topups SET state=?,reviewed_at=?,reviewed_by=?,note=? WHERE id=?", (target, now(), actor, note[:500], invoice_id))
            self.audit(db, actor, "Пополнение подтверждено" if approve else "Пополнение отклонено", invoice_id)
            result = dict(db.execute("SELECT * FROM topups WHERE id=?", (invoice_id,)).fetchone())
            self._enqueue(db, {"method": "sendMessage", "data": {"chat_id": result["user_id"], "text": (f"✅ Пополнение подтверждено. Зачислено {rub(result['rub_kopeks'])} ₽." if approve else "Пополнение отклонено. "+(note[:500] or "Обратитесь в поддержку."))}}, "review:"+invoice_id)
        return result

    def support_send(self, user_id: int, text: str) -> str:
        text = str(text).strip()
        if not 1 <= len(text) <= 3500:
            raise Fault("Сообщение должно содержать от 1 до 3500 символов")
        with self.transaction() as db:
            ticket = db.execute("SELECT id FROM tickets WHERE user_id=? AND state='open' ORDER BY updated_at DESC LIMIT 1", (user_id,)).fetchone()
            ticket_id = ticket["id"] if ticket else uid()
            if not ticket:
                db.execute("INSERT INTO tickets(id,user_id,created_at,updated_at) VALUES(?,?,?,?)", (ticket_id, user_id, now(), now()))
            db.execute("INSERT INTO support_messages VALUES(?,?,?,?,?)", (uid(), ticket_id, "client", self.vault.seal(text), now()))
            db.execute("UPDATE tickets SET updated_at=? WHERE id=?", (now(), ticket_id))
        self.notify_admins(f"💬 Поддержка · #{ticket_id[:8]}\nПользователь {user_id}\n\n{html.escape(text)}", {"inline_keyboard": [[{"text": "Ответить", "callback_data": "reply:"+ticket_id}]]})
        return ticket_id

    def support_reply(self, actor: int, ticket_id: str, text: str) -> None:
        text = str(text).strip()
        if not 1 <= len(text) <= 3500:
            raise Fault("Ответ должен содержать от 1 до 3500 символов")
        with self.transaction() as db:
            ticket = db.execute("SELECT * FROM tickets WHERE id=?", (ticket_id,)).fetchone()
            if not ticket:
                raise Fault("Обращение не найдено", 404)
            message_id = uid()
            db.execute("INSERT INTO support_messages VALUES(?,?,?,?,?)", (message_id, ticket_id, "admin", self.vault.seal(text), now()))
            db.execute("UPDATE tickets SET updated_at=?,state='open' WHERE id=?", (now(), ticket_id))
            self.audit(db, actor, "Ответ клиенту в поддержку", ticket_id)
            self._enqueue(db, {"method": "sendMessage", "data": {"chat_id": ticket["user_id"], "text": f"💬 Ответ поддержки acczLOL\nОбращение #{ticket_id[:8]}\n\n{text}"}}, "support:"+message_id)

    def support_data(self, user_id: int | None = None, ticket_id: str | None = None) -> dict:
        if user_id is None:
            tickets = self.query("SELECT t.*,u.name,u.username FROM tickets t JOIN users u ON u.id=t.user_id ORDER BY t.updated_at DESC LIMIT 100")
        else:
            tickets = self.query("SELECT * FROM tickets WHERE user_id=? ORDER BY updated_at DESC", (user_id,))
        selected = next((t for t in tickets if t["id"] == ticket_id), None) if ticket_id else (tickets[0] if tickets else None)
        messages = self.query("SELECT id,actor,body_enc,created_at FROM support_messages WHERE ticket_id=? ORDER BY created_at,rowid", (selected["id"],)) if selected else []
        for m in messages:
            m["body"] = self.vault.open(m.pop("body_enc"))
        return {"tickets": tickets, "selected": selected, "messages": messages}

    def claim_job(self, worker: str) -> dict | None:
        with self.transaction() as db:
            expired = db.execute("SELECT * FROM jobs WHERE state='checking' AND lease_until<? AND attempts>=3", (now(),)).fetchall()
            for job in expired:
                self._fail_job(db, dict(job), "WORKER_TIMEOUT")
            row = db.execute("SELECT * FROM jobs WHERE (state='waiting' OR (state='checking' AND lease_until<?)) AND retry_at<=? AND attempts<3 ORDER BY created_at,id LIMIT 1", (now(), now())).fetchone()
            if not row:
                return None
            db.execute("UPDATE jobs SET state='checking',stage='Подключение',worker_id=?,lease_until=?,attempts=attempts+1,updated_at=? WHERE id=?", (worker, now()+self.settings.lease_seconds, now(), row["id"]))
            return dict(db.execute("SELECT * FROM jobs WHERE id=?", (row["id"],)).fetchone())

    def heartbeat(self, job_id: str, worker: str) -> bool:
        return bool(self.execute("UPDATE jobs SET lease_until=? WHERE id=? AND worker_id=? AND state='checking' AND lease_until>?", (now()+self.settings.lease_seconds, job_id, worker, now())))

    def stage(self, job_id: str, worker: str, text: str) -> None:
        with self.transaction() as db:
            if not db.execute("UPDATE jobs SET stage=?,updated_at=? WHERE id=? AND worker_id=? AND state='checking' AND lease_until>?", (text, now(), job_id, worker, now())).rowcount:
                raise Fault("Владение задачей утрачено", 409)
            self.audit(db, "Агент", text, job_id)

    @staticmethod
    def _refund(db: sqlite3.Connection, order: dict | sqlite3.Row, actor: Any, reason: str) -> None:
        if order["state"] not in ("checking", "complete"):
            return
        event_key = "refund:"+order["id"]
        inserted = db.execute("INSERT OR IGNORE INTO ledger(user_id,delta,kind,event_key,reference,created_at) VALUES(?,?,'refund',?,?,?)", (order["user_id"], order["amount"], event_key, order["id"], now())).rowcount
        if inserted:
            db.execute("UPDATE users SET balance=balance+? WHERE id=?", (order["amount"], order["user_id"]))
        db.execute("UPDATE orders SET state='refunded',error_code=? WHERE id=?", (reason, order["id"]))
        db.execute("UPDATE accounts SET state='attention' WHERE id=?", (order["account_id"],))
        Store.audit(db, actor, "Возврат на баланс", order["id"], reason)

    def refund(self, actor: int, order_id: str, reason: str) -> None:
        with self.transaction() as db:
            order = db.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
            if not order:
                raise Fault("Заказ не найден", 404)
            self._refund(db, order, actor, reason[:100] or "ADMIN_REFUND")

    def _fail_job(self, db: sqlite3.Connection, job: dict, error: str) -> None:
        db.execute("UPDATE jobs SET state='error',stage='Требует внимания',error_code=?,updated_at=?,lease_until=0 WHERE id=?", (error, now(), job["id"]))
        if job["kind"] == "validate":
            db.execute("UPDATE accounts SET state='attention' WHERE id=?", (job["account_id"],))
        if job["kind"] == "fulfill" and job["order_id"]:
            order = db.execute("SELECT * FROM orders WHERE id=?", (job["order_id"],)).fetchone()
            if order:
                self._refund(db, order, "Агент", error)
        self.audit(db, "Агент", "Задача завершена с ошибкой", job["id"], error)

    def fail_job(self, job: dict, worker: str, error: str) -> None:
        with self.transaction() as db:
            current = db.execute("SELECT * FROM jobs WHERE id=? AND worker_id=? AND state='checking' AND lease_until>?", (job["id"], worker, now())).fetchone()
            if current:
                self._fail_job(db, dict(current), error)

    def finish_job(self, job: dict, worker: str, result: dict) -> bool:
        with self.transaction() as db:
            current = db.execute("SELECT * FROM jobs WHERE id=? AND worker_id=? AND state='checking' AND lease_until>?", (job["id"], worker, now())).fetchone()
            if not current:
                return False
            if job["kind"] in ("fulfill", "code"):
                order = db.execute("SELECT * FROM orders WHERE id=?", (job["order_id"],)).fetchone()
                if not order or order["state"] not in (("checking",) if job["kind"] == "fulfill" else ("complete",)):
                    self._fail_job(db, job, "ORDER_ACCESS_CLOSED")
                    return False
            if "has_password" in result:
                account_secret = db.execute("SELECT secret_enc FROM accounts WHERE id=?", (job["account_id"],)).fetchone()
                secret = self.vault.open(account_secret["secret_enc"])
                secret["password_active"] = bool(result["has_password"] and result.get("password_valid"))
                db.execute("UPDATE accounts SET secret_enc=? WHERE id=?", (self.vault.seal(secret), job["account_id"]))
            if job["kind"] == "validate":
                report = result["report"]
                try:
                    db.execute("UPDATE accounts SET telegram_id=?,state=?,score=?,security_json=?,username=?,login_enc=?,checked_at=? WHERE id=?", (result.get("telegram_id"), "available" if report["publishable"] else "attention", report["score"], json.dumps(report), result.get("username", ""), self.vault.seal({"login": result["login"]}), now(), job["account_id"]))
                except sqlite3.IntegrityError:
                    raise Fault("ACCOUNT_DUPLICATE") from None
            elif job["kind"] == "fulfill":
                db.execute("UPDATE accounts SET state='sold',username=?,login_enc=?,checked_at=? WHERE id=?", (result.get("username", ""), self.vault.seal({"login": result["login"]}), now(), job["account_id"]))
                db.execute("UPDATE orders SET state='complete',completed_at=? WHERE id=?", (now(), job["order_id"]))
            elif job["kind"] == "code":
                db.execute("UPDATE accounts SET last_code_message_id=? WHERE id=?", (result["message_id"], job["account_id"]))
            code_result = {"code": result["code"]} if job["kind"] == "code" else {}
            db.execute("UPDATE jobs SET state='ready',stage='Готово',result_enc=?,result_expires=?,updated_at=?,lease_until=0 WHERE id=?", (self.vault.seal(code_result), now()+self.settings.code_ttl if code_result else 0, now(), job["id"]))
            if job["kind"] == "fulfill":
                self._enqueue(db, {"method": "sendMessage", "data": {"chat_id": job["user_id"], "text": f"✅ Заказ #{job['order_id'][:8]} готов.\nЛогин: {result['login']}\nКод можно получить кнопкой ниже.", "reply_markup": {"inline_keyboard": [[{"text": "Получить код", "callback_data": "code:"+job["order_id"]}],[{"text": "Обратиться в поддержку", "callback_data": "support"}]]}}}, "delivery:"+job["order_id"])
            if job["kind"] == "code" and self.vault.open(current["payload_enc"]).get("origin") == "bot":
                self._enqueue(db, {"method": "sendMessage", "data": {"chat_id": job["user_id"], "text": f"Код для вашего заказа #{job['order_id'][:8]}: {result['code']}\nАвтоматическое удаление через {self.settings.code_ttl} секунд.", "parse_mode": "HTML"}, "expire_after": self.settings.code_ttl, "expires_at": now()+self.settings.code_ttl}, "code:"+job["id"])
            self.audit(db, "Агент", "Операция завершена", job["id"])
        return True


def validate_init_data(raw: str, bot_token: str, max_age: int = 3600, stamp: int | None = None) -> dict:
    if not bot_token or not raw or len(raw) > 16000:
        raise Fault("Откройте приложение из Telegram-бота", 401)
    try:
        pairs = urllib.parse.parse_qsl(raw, keep_blank_values=True, strict_parsing=True)
        if len({k for k, _ in pairs}) != len(pairs):
            raise ValueError("duplicate fields")
        fields = dict(pairs)
        given = fields.pop("hash")
        data_check = "\n".join(f"{key}={fields[key]}" for key in sorted(fields))
        key = hmac.new(b"WebAppData", bot_token.encode(), hashlib.sha256).digest()
        expected = hmac.new(key, data_check.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(given, expected):
            raise ValueError("signature")
        date = int(fields["auth_date"])
        current = stamp if stamp is not None else now()
        if date < current-max_age or date > current+30:
            raise ValueError("expired")
        user = json.loads(fields["user"])
        if type(user.get("id")) is not int or user["id"] <= 0:
            raise ValueError("user")
        return user
    except (KeyError, ValueError, TypeError):
        raise Fault("Подпись Telegram недействительна или срок входа истёк", 401) from None


class RateLimiter:
    def __init__(self):
        self.items: dict[str, deque] = defaultdict(deque)

    def check(self, key: str, limit: int, window: int) -> None:
        queue = self.items[key]
        cutoff = time.monotonic()-window
        while queue and queue[0] < cutoff:
            queue.popleft()
        if len(queue) >= limit:
            raise Fault("Слишком много попыток. Попробуйте позже", 429)
        queue.append(time.monotonic())
        if len(self.items) > 10000:
            self.items = defaultdict(deque, {k: v for k, v in self.items.items() if v and v[-1] > cutoff})


class PriceFeed:
    def __init__(self, http: aiohttp.ClientSession, settings: Settings):
        self.http, self.settings = http, settings
        self.cached: tuple[Decimal, str, int] | None = None
        self.lock = asyncio.Lock()

    async def quote(self) -> tuple[Decimal, str]:
        async with self.lock:
            if self.cached and self.cached[2] > now()-60:
                return self.cached[0], self.cached[1]
            try:
                headers = {"x-cg-demo-api-key": self.settings.cg_key} if self.settings.cg_key else {}
                async with self.http.get("https://api.coingecko.com/api/v3/simple/price", params={"ids": "litecoin", "vs_currencies": "rub", "include_last_updated_at": "true"}, headers=headers, timeout=aiohttp.ClientTimeout(total=10)) as response:
                    response.raise_for_status()
                    data = json.loads(await response.text(), parse_float=Decimal)["litecoin"]
                    rate = Decimal(str(data["rub"]))
                    if not rate.is_finite() or rate <= 0 or int(data.get("last_updated_at", now())) < now()-600:
                        raise ValueError("stale quote")
                    self.cached = (rate, "CoinGecko LTC/RUB", now())
                    return rate, self.cached[1]
            except (aiohttp.ClientError, asyncio.TimeoutError, KeyError, ValueError, InvalidOperation):
                pass
            try:
                async with self.http.get("https://api.kraken.com/0/public/Ticker", params={"pair": "LTCUSD"}, timeout=aiohttp.ClientTimeout(total=10)) as response:
                    response.raise_for_status()
                    data = await response.json()
                    if data.get("error"):
                        raise ValueError("ticker unavailable")
                    usd = Decimal(next(iter(data["result"].values()))["c"][0])
                async with self.http.get("https://www.cbr.ru/scripts/XML_daily.asp", timeout=aiohttp.ClientTimeout(total=10)) as response:
                    response.raise_for_status()
                    root = ET.fromstring(await response.read())
                usd_node = next(v for v in root.findall("Valute") if v.findtext("CharCode") == "USD")
                fx = Decimal(usd_node.findtext("Value").replace(",", "."))/Decimal(usd_node.findtext("Nominal"))
                source_date = datetime.strptime(root.attrib["Date"], "%d.%m.%Y").replace(tzinfo=timezone.utc)
                if now()-source_date.timestamp() > 8*86400:
                    raise ValueError("stale FX")
                rate = usd*fx
                if not rate.is_finite() or rate <= 0:
                    raise ValueError("invalid rate")
                self.cached = (rate, f"Kraken LTC/USD × ЦБ USD/RUB ({root.attrib['Date']})", now())
                return rate, self.cached[1]
            except (aiohttp.ClientError, asyncio.TimeoutError, KeyError, ValueError, StopIteration, InvalidOperation, ET.ParseError):
                raise Fault("Курс LTC/RUB сейчас недоступен. Попробуйте позже; заявка не создана", 503) from None


