def normalize_session(raw: str | bytes) -> str:
    try:
        from telethon.sessions import MemorySession, StringSession
        from telethon.crypto import AuthKey
    except ImportError:
        raise Fault("Установите Telethon на сервере", 503) from None
    try:
        if isinstance(raw, bytes) and raw.startswith(b"SQLite format 3\x00"):
            if len(raw) > 5_000_000:
                raise ValueError("large session")
            with sqlite3.connect(":memory:") as db:
                db.deserialize(raw)
                db.execute("PRAGMA trusted_schema=OFF")
                db.execute("PRAGMA query_only=ON")
                deadline = time.monotonic()+1
                db.set_progress_handler(lambda: int(time.monotonic() > deadline), 1000)
                row = db.execute("SELECT dc_id,server_address,port,auth_key FROM sessions LIMIT 1").fetchone()
            if not row or not isinstance(row[3], bytes) or len(row[3]) != 256:
                raise ValueError("invalid auth key")
            session = MemorySession()
            session.set_dc(int(row[0]), str(row[1]), int(row[2]))
            session.auth_key = AuthKey(row[3])
            text = StringSession.save(session)
        else:
            text = (raw.decode("utf-8") if isinstance(raw, bytes) else raw).strip()
        parsed = StringSession(text)
        if not parsed.auth_key or len(parsed.auth_key.key) != 256 or not 1 <= parsed.dc_id <= 5:
            raise ValueError("invalid session")
        address = ipaddress.ip_address(parsed.server_address)
        if not address.is_global or parsed.port not in (80, 443, 5222):
            raise ValueError("invalid datacenter")
        return text
    except (ValueError, TypeError, sqlite3.Error, UnicodeError, AttributeError, binascii.Error, struct.error):
        raise Fault("Нужна авторизованная Telethon StringSession или файл .session. Архив tdata не поддерживается") from None


def extract_login_code(message: str) -> str | None:
    if not re.search(r"code|код|código|codice|kodu|رمز|کد|登录|登入|인증|コード", message, re.I):
        return None
    result = re.search(r"(?<![\d-])((?:\d-*){5,7})(?![\d-])", message)
    return result.group(1).replace("-", "") if result else None


class MTProtoAgent:
    def __init__(self, store: Store, settings: Settings):
        self.store, self.settings = store, settings
        self.worker_id = uid()
        self.tasks: set[asyncio.Task] = set()

    async def run(self):
        while True:
            for task in self.tasks:
                if task.done() and not task.cancelled():
                    error = task.exception()
                    if error:
                        LOG.error("Agent task stopped: %s", type(error).__name__)
            self.tasks = {t for t in self.tasks if not t.done()}
            if len(self.tasks) < self.settings.worker_concurrency:
                job = await asyncio.to_thread(self.store.claim_job, self.worker_id)
                if job:
                    task = asyncio.create_task(self.work(job))
                    self.tasks.add(task)
                    continue
            await asyncio.sleep(1)

    async def work(self, job: dict):
        current_task = asyncio.current_task()
        async def beat():
            while True:
                await asyncio.sleep(max(10, self.settings.lease_seconds//3))
                if not await asyncio.to_thread(self.store.heartbeat, job["id"], self.worker_id):
                    current_task.cancel()
                    return
        heartbeat = asyncio.create_task(beat())
        client = None
        try:
            if self.settings.demo:
                if job["kind"] == "code":
                    raise Fault("DEMO_NO_CODE")
                await asyncio.sleep(.35)
                result = {"login": "DEMO-"+job["account_id"][:8], "username": "demo_account", "report": {"score": 82, "publishable": True, "factors": {}, "demo": True}}
            else:
                if not self.settings.api_id or not self.settings.api_hash:
                    raise Fault("API_NOT_CONFIGURED")
                from telethon import TelegramClient, errors
                from telethon.sessions import StringSession
                from telethon.tl.functions.account import GetPasswordRequest, GetAuthorizationsRequest, GetPasswordSettingsRequest
                from telethon.password import compute_check
                account = await asyncio.to_thread(self.store.one, "SELECT * FROM accounts WHERE id=?", (job["account_id"],))
                if not account:
                    raise Fault("ACCOUNT_UNAVAILABLE")
                secret = self.store.vault.open(account["secret_enc"])
                client = TelegramClient(StringSession(secret["session"]), self.settings.api_id, self.settings.api_hash,
                    device_model="acczLOL Agent", system_version="Server", app_version="1.0", connection_retries=2,
                    request_retries=2, flood_sleep_threshold=0, receive_updates=False, timeout=15)
                await asyncio.wait_for(client.connect(), 25)
                if not await asyncio.wait_for(client.is_user_authorized(), 15):
                    raise Fault("SESSION_EXPIRED")
                me = await asyncio.wait_for(client.get_me(), 15)
                if not me or getattr(me, "bot", False) or not getattr(me, "phone", None):
                    raise Fault("ACCOUNT_UNAVAILABLE")
                await asyncio.to_thread(self.store.stage, job["id"], self.worker_id, "Вход в сессию подтверждён")
                if account.get("telegram_id") and int(me.id) != account["telegram_id"]:
                    raise Fault("ACCOUNT_UNAVAILABLE")
                result = {"telegram_id": int(me.id), "login": "+"+str(me.phone).lstrip("+"), "username": getattr(me, "username", "") or ""}
                password = None
                password_valid = False
                if job["kind"] in ("validate", "fulfill"):
                    password = await asyncio.wait_for(client(GetPasswordRequest()), 15)
                    if password.has_password and secret.get("password"):
                        proof = await asyncio.to_thread(compute_check, password, secret["password"])
                        try:
                            await asyncio.wait_for(client(GetPasswordSettingsRequest(proof)), 15)
                            password_valid = True
                        except errors.PasswordHashInvalidError:
                            if job["kind"] == "fulfill":
                                raise Fault("ACCOUNT_UNAVAILABLE") from None
                    if job["kind"] == "fulfill" and password.has_password and not password_valid:
                        raise Fault("ACCOUNT_UNAVAILABLE")
                    result["has_password"] = bool(password.has_password)
                    result["password_valid"] = password_valid
                if job["kind"] == "validate":
                    await asyncio.to_thread(self.store.stage, job["id"], self.worker_id, "Проверка безопасности")
                    auths = await asyncio.wait_for(client(GetAuthorizationsRequest()), 15)
                    factors = {"authorized": "pass", "twofa": "pass" if password_valid else "unknown" if password.has_password else "fail",
                        "recovery": "pass" if password.has_recovery else "unknown",
                        "sessions": "pass" if len(auths.authorizations) <= 1 else "fail"}
                    policy = self.store.policy()
                    total = sum(policy["weights"].values())
                    score = round(100*sum(weight for key, weight in policy["weights"].items() if factors[key] == "pass")/total)
                    result["report"] = {"score": score, "factors": factors, "version": policy["version"],
                        "sessions_count": len(auths.authorizations), "checked_at": now(),
                        "publishable": score >= policy["publish_threshold"] and (not password.has_password or password_valid)}
                elif job["kind"] == "code":
                    await asyncio.to_thread(self.store.stage, job["id"], self.worker_id, "Ожидание свежего кода Telegram")
                    order = self.store.one("SELECT * FROM orders WHERE id=?", (job["order_id"],))
                    deadline = time.monotonic()+self.settings.code_wait
                    found = None
                    while time.monotonic() < deadline:
                        fresh_order = self.store.one("SELECT state FROM orders WHERE id=?", (job["order_id"],))
                        if not fresh_order or fresh_order["state"] != "complete":
                            raise Fault("ORDER_ACCESS_CLOSED")
                        messages = await asyncio.wait_for(client.get_messages(777000, limit=8), 15)
                        earliest = max(order["created_at"]-5, now()-self.settings.code_max_age)
                        for message in messages:
                            if message.id <= account["last_code_message_id"] or message.date.timestamp() < earliest or message.out:
                                continue
                            code = extract_login_code(message.raw_text or "")
                            if code:
                                found = {"code": code, "message_id": message.id}
                                break
                        if found:
                            break
                        await asyncio.sleep(2)
                    if not found:
                        raise Fault("CODE_TIMEOUT")
                    result = found
            completed = await asyncio.to_thread(self.store.finish_job, job, self.worker_id, result)
            if completed and job["kind"] == "fulfill":
                self.store.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": job["user_id"], "text": f"✅ Заказ #{job['order_id'][:8]} готов.\nЛогин: {result['login']}\nКод можно получить кнопкой ниже.", "reply_markup": {"inline_keyboard": [[{"text": "Получить код", "callback_data": "code:"+job["order_id"]}],[{"text": "Обратиться в поддержку", "callback_data": "support"}]]}}}, "delivery:"+job["order_id"])
            if completed and job["kind"] == "code":
                payload_row = self.store.one("SELECT payload_enc FROM jobs WHERE id=?", (job["id"],))
                payload = self.store.vault.open(payload_row["payload_enc"])
                if payload.get("origin") == "bot":
                    self.store.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": job["user_id"], "text": f"Код для вашего заказа #{job['order_id'][:8]}: <code>{result['code']}</code>\nСообщение будет удалено через {self.settings.code_ttl} секунд.", "parse_mode": "HTML"}, "expire_after": self.settings.code_ttl, "expires_at": now()+self.settings.code_ttl}, "code:"+job["id"])
        except asyncio.CancelledError:
            raise
        except Exception as error:
            name = type(error).__name__
            code = str(error) if isinstance(error, Fault) and str(error) in ERROR_TEXT else "SESSION_EXPIRED" if name in ("AuthKeyUnregisteredError", "SessionRevokedError", "UserDeactivatedError", "AuthKeyDuplicatedError") else "OPERATION_FAILED"
            if name == "FloodWaitError" and job["attempts"] < 3:
                delay = max(1, min(int(getattr(error, "seconds", 60)), 86400))
                self.store.execute("UPDATE jobs SET state='waiting',stage='Ожидание лимита Telegram',retry_at=?,lease_until=0,updated_at=? WHERE id=? AND worker_id=? AND state='checking'", (now()+delay, now(), job["id"], self.worker_id))
            else:
                code = "FLOOD_WAIT" if name == "FloodWaitError" else code
                await asyncio.to_thread(self.store.fail_job, job, self.worker_id, code)
                if job["kind"] == "fulfill":
                    self.store.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": job["user_id"], "text": f"Заказ #{job['order_id'][:8]} не удалось выдать. Проверьте статус и возврат в истории. Поддержка поможет решить вопрос."}}, "delivery-error:"+job["id"])
            LOG.warning("Agent job %s: %s", job["id"][:8], code)
        finally:
            heartbeat.cancel()
            with contextlib.suppress(asyncio.CancelledError):
                await heartbeat
            if client:
                with contextlib.suppress(Exception):
                    await asyncio.wait_for(client.disconnect(), 10)


class TelegramAPI:
    def __init__(self, http: aiohttp.ClientSession, settings: Settings, store: Store):
        self.http, self.settings, self.store = http, settings, store
        self.emoji_ok = True
        self.stickers: dict[str, dict] = {}
        self.emoji_files: dict[str, tuple[bytes, str]] = {}
        self.limiter = RateLimiter()

    async def call(self, method: str, data: dict | None = None, file: tuple[str, bytes, str, str] | None = None, timeout: int = 20) -> Any:
        if not self.settings.bot_token or self.settings.demo:
            raise Fault("Бот не подключён", 503)
        endpoint = f"https://api.telegram.org/bot{self.settings.bot_token}/{method}"
        async def perform(payload: dict, upload):
            if upload:
                form = aiohttp.FormData()
                for key, value in payload.items():
                    form.add_field(key, json.dumps(value, ensure_ascii=False) if isinstance(value, (dict, list, bool)) else str(value))
                field, content, filename, mime = upload
                form.add_field(field, content, filename=filename, content_type=mime)
                request = self.http.post(endpoint, data=form, timeout=aiohttp.ClientTimeout(total=timeout))
            else:
                request = self.http.post(endpoint, json=payload, timeout=aiohttp.ClientTimeout(total=timeout))
            async with request as response:
                result = await response.json(content_type=None)
            if not result.get("ok"):
                description = str(result.get("description", "Telegram API error")).replace(self.settings.bot_token, "[redacted]")
                raise Fault(description, 502)
            return result.get("result")
        payload = data or {}
        try:
            return await perform(payload, file)
        except Fault as error:
            if any(x in str(error).lower() for x in ("custom emoji", "custom_emoji", "premium", "icon_custom_emoji_id")):
                self.emoji_ok = False
                def strip(value):
                    if isinstance(value, dict):
                        return {k: strip(v) for k, v in value.items() if k != "icon_custom_emoji_id"}
                    return [strip(v) for v in value] if isinstance(value, list) else value
                return await perform(strip(payload), file)
            raise

    def button(self, title: str, *, action: str = "", screen: str = "", icon: str = "") -> dict:
        result: dict = {"text": title}
        if screen:
            result["web_app"] = {"url": self.settings.public_url+"/?"+urllib.parse.urlencode({"screen": screen})}
        else:
            result["callback_data"] = action
        if icon and self.emoji_ok:
            result["icon_custom_emoji_id"] = EMOJI[icon]
        return result

    def menu(self) -> dict:
        return {"inline_keyboard": [
            [self.button("Каталог аккаунтов", screen="catalog", icon="catalog"), self.button("Ваш баланс", action="balance", icon="balance")],
            [self.button("Найти аккаунты", action="find", icon="find"), self.button("История покупок", screen="history", icon="history")],
            [self.button("Связь с поддержкой", action="support", icon="support"), self.button("Пополнение баланса", screen="topup", icon="topup")],
            [self.button("Открыть acczLOL ↗", screen="catalog")],
            [self.button("Админ-вход · ввести ключ", action="admin"), self.button("Вход на ПК", action="browser_login")],
        ]}

    async def message(self, chat_id: int, text: str, keyboard: dict | None = None) -> Any:
        return await self.call("sendMessage", {"chat_id": chat_id, "text": text, "parse_mode": "HTML", **({"reply_markup": keyboard} if keyboard else {})})

    async def start_menu(self, user: dict, assets: dict) -> None:
        photo = assets.get("menu.jpg")
        caption = f"<b>acczLOL</b>\n\nTelegram-аккаунты, покупки и поддержка в одном приложении.\n\nВаш баланс: <b>{rub(user['balance'])} ₽</b>\nВыберите нужный раздел ниже."
        if photo:
            await self.call("sendPhoto", {"chat_id": user["id"], "caption": caption, "parse_mode": "HTML", "reply_markup": self.menu()}, ("photo", photo[0], "acczLOL.jpg", "image/jpeg"))
        else:
            await self.message(user["id"], caption, self.menu())
        try:
            stickers = await self.call("getCustomEmojiStickers", {"custom_emoji_ids": [EMOJI["final"]]})
            if stickers:
                await self.call("sendSticker", {"chat_id": user["id"], "sticker": stickers[0]["file_id"]})
                return
        except (Fault, aiohttp.ClientError, asyncio.TimeoutError):
            pass
        try:
            await self.message(user["id"], f'<tg-emoji emoji-id="{EMOJI["final"]}">✨</tg-emoji>')
        except (Fault, aiohttp.ClientError, asyncio.TimeoutError):
            with contextlib.suppress(Exception):
                await self.message(user["id"], "✨")

    async def warm_emoji(self):
        result = await self.call("getCustomEmojiStickers", {"custom_emoji_ids": list(EMOJI.values())})
        self.stickers = {s.get("custom_emoji_id", ""): s for s in result}

    async def emoji_asset(self, emoji_id: str) -> tuple[bytes, str] | None:
        if emoji_id in self.emoji_files:
            return self.emoji_files[emoji_id]
        sticker = self.stickers.get(emoji_id)
        if not sticker:
            return None
        thumbnail = sticker.get("thumbnail") or {}
        file_id = thumbnail.get("file_id") or (sticker["file_id"] if not sticker.get("is_animated") and not sticker.get("is_video") else "")
        if not file_id:
            return None
        item = await self.call("getFile", {"file_id": file_id})
        async with self.http.get(f"https://api.telegram.org/file/bot{self.settings.bot_token}/{item['file_path']}", timeout=aiohttp.ClientTimeout(total=15)) as response:
            response.raise_for_status()
            body = await response.content.read(2_000_001)
            if len(body) > 2_000_000:
                return None
        result = (body, mimetypes.guess_type(item["file_path"])[0] or "image/webp")
        self.emoji_files[emoji_id] = result
        return result

    async def handle_update(self, update: dict, assets: dict):
        update_id = int(update["update_id"])
        if self.store.one("SELECT id FROM processed_updates WHERE id=?", (update_id,)):
            return
        callback = update.get("callback_query")
        message = update.get("message")
        sender = (callback or {}).get("from") or (message or {}).get("from")
        if not sender or sender.get("is_bot"):
            return
        user = self.store.user(sender)
        self.limiter.check(f"bot:{user['id']}", 60, 60)
        if callback:
            data = str(callback.get("data", ""))
            with contextlib.suppress(Exception):
                await self.call("answerCallbackQuery", {"callback_query_id": callback["id"]})
            if data == "balance":
                await self.message(user["id"], f"Ваш баланс: <b>{rub(user['balance'])} ₽</b>", {"inline_keyboard": [[self.button("Пополнить баланс", screen="topup", icon="topup")]]})
            elif data == "find":
                self.store.set_bot_state(user["id"], "find_min")
                await self.message(user["id"], "Введите минимальную цену в рублях. Например: <code>500</code>\nОтмена: /cancel")
            elif data == "support":
                self.store.set_bot_state(user["id"], "support")
                await self.message(user["id"], "Напишите вопрос одним сообщением. Администратор увидит его в веб-приложении, а ответ придёт сюда.\nВыход: /cancel")
            elif data == "admin":
                self.store.set_bot_state(user["id"], "admin_key")
                await self.message(user["id"], "Введите админ-ключ. Сообщение с ключом будет удалено после проверки.\nОтмена: /cancel")
            elif data == "browser_login":
                code = self.store.app_login_code(user["id"])
                await self.message(user["id"], f"Код входа в acczLOL на ПК:\n<code>{code}</code>\n\nОдноразовый, действует 3 минуты. Это код только для нашего сайта, не для входа в Telegram.")
            elif data.startswith("reply:"):
                if user["admin_until"] <= now():
                    raise Fault("Сначала выполните административный вход")
                self.store.set_bot_state(user["id"], "reply", {"ticket_id": data.split(":", 1)[1]})
                await self.message(user["id"], "Введите ответ клиенту. Он придёт в личный чат с ботом.")
            elif data.startswith("code:"):
                job_id = self.store.request_code(user["id"], data.split(":", 1)[1], "bot")
                ready = self.store.job_result(user["id"], job_id)
                if ready["state"] == "ready":
                    self.store.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": user["id"], "text": f"Код для вашего заказа: {ready['code']}"}, "expire_after": max(1, ready["expires_at"]-now()), "expires_at": ready["expires_at"]}, "cached-code:"+job_id)
                    await self.message(user["id"], "Код отправлен в этот чат.")
                else:
                    await self.message(user["id"], f"Ожидаю свежий код для вашего заказа. Перед этим запросите вход в Telegram по выданному логину.\nЗадача: <code>{job_id[:8]}</code>")
        elif message and message.get("chat", {}).get("type") == "private":
            text = str(message.get("text", "")).strip()
            state, payload = self.store.bot_state(user["id"])
            if text.split(" ", 1)[0].split("@")[0] == "/start":
                self.store.clear_bot_state(user["id"])
                await self.start_menu(user, assets)
            elif text == "/cancel":
                self.store.clear_bot_state(user["id"])
                await self.message(user["id"], "Действие отменено.", self.menu())
            elif text == "/login":
                code = self.store.app_login_code(user["id"])
                await self.message(user["id"], f"Код входа в acczLOL: <code>{code}</code>\nДействует 3 минуты, одноразовый.")
            elif text == "/balance":
                await self.message(user["id"], f"Ваш баланс: <b>{rub(user['balance'])} ₽</b>", self.menu())
            elif state == "admin_key":
                self.limiter.check(f"admin-bot:{user['id']}", 5, 900)
                with contextlib.suppress(Exception):
                    await self.call("deleteMessage", {"chat_id": user["id"], "message_id": message["message_id"]})
                self.store.unlock_admin(user["id"], text)
                self.store.clear_bot_state(user["id"])
                await self.message(user["id"], "Административный доступ открыт на 12 часов.", {"inline_keyboard": [[self.button("Открыть админ-панель", screen="admin")]]})
            elif state == "find_min":
                minimum = money_input(text, allow_zero=True)
                self.store.set_bot_state(user["id"], "find_max", {"minimum": minimum})
                await self.message(user["id"], "Теперь укажите максимальную цену в рублях.")
            elif state == "find_max":
                maximum = money_input(text)
                if maximum < payload["minimum"]:
                    raise Fault("Максимальная цена должна быть не меньше минимальной")
                items = self.store.catalog(payload["minimum"], maximum)
                self.store.clear_bot_state(user["id"])
                lines = [f"Найдено аккаунтов: <b>{len(items)}</b>"]
                lines += [f"• {html.escape(a['title'])} — <b>{a['price_rub']} ₽</b> · {a['score'] if a['score'] is not None else '—'}/100" for a in items[:10]]
                link = self.settings.public_url+"/?"+urllib.parse.urlencode({"screen": "catalog", "min": rub(payload["minimum"]), "max": rub(maximum)})
                await self.message(user["id"], "\n".join(lines), {"inline_keyboard": [[{"text": "Открыть результаты", "web_app": {"url": link}, **({"icon_custom_emoji_id": EMOJI['find']} if self.emoji_ok else {})}]]})
            elif state == "reply":
                if user["admin_until"] <= now():
                    raise Fault("Административный вход истёк", 403)
                self.store.support_reply(user["id"], payload["ticket_id"], text)
                self.store.clear_bot_state(user["id"])
                await self.message(user["id"], "Ответ поставлен в доставку клиенту.")
            elif text and not text.startswith("/"):
                ticket = self.store.support_send(user["id"], text)
                await self.message(user["id"], f"Сообщение передано в поддержку. Обращение <code>#{ticket[:8]}</code>. Ответ придёт в этот чат.")
            else:
                await self.message(user["id"], "Используйте меню ниже. /cancel — отмена, /login — вход на ПК.", self.menu())
        self.store.execute("INSERT OR IGNORE INTO processed_updates VALUES(?,?)", (update_id, now()))

    async def polling(self, assets: dict):
        await self.call("deleteWebhook", {"drop_pending_updates": False})
        offset = int((self.store.one("SELECT value FROM settings WHERE key='tg_offset'") or {}).get("value", "0"))
        while True:
            try:
                updates = await self.call("getUpdates", {"offset": offset, "timeout": 40, "allowed_updates": ["message", "callback_query"]}, timeout=50)
                for update in updates:
                    try:
                        await self.handle_update(update, assets)
                    except Fault as error:
                        sender = update.get("message", {}).get("from", {}) or update.get("callback_query", {}).get("from", {})
                        if sender.get("id"):
                            with contextlib.suppress(Exception):
                                await self.message(sender["id"], html.escape(str(error)))
                    except Exception as error:
                        LOG.error("Bot update failed: %s", type(error).__name__)
                    offset = update["update_id"]+1
                    self.store.execute("INSERT INTO settings VALUES('tg_offset',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(offset),))
            except asyncio.CancelledError:
                raise
            except Exception as error:
                LOG.warning("Polling paused: %s", type(error).__name__)
                await asyncio.sleep(5)

    async def outbox(self):
        while True:
            rows = self.store.query("SELECT * FROM outbox WHERE (state='waiting' OR (state='sending' AND lease_until<?)) AND due_at<=? ORDER BY created_at LIMIT 20", (now(), now()))
            for row in rows:
                claimed = self.store.execute("UPDATE outbox SET state='sending',attempts=attempts+1,lease_until=? WHERE id=? AND (state='waiting' OR (state='sending' AND lease_until<?))", (now()+60, row["id"], now()))
                if not claimed:
                    continue
                payload = self.store.vault.open(row["payload_enc"])
                if payload.get("expires_at") and payload["expires_at"] <= now():
                    self.store.execute("UPDATE outbox SET state='failed',payload_enc=? WHERE id=?", (self.store.vault.seal({}), row["id"]))
                    continue
                try:
                    result = await self.call(payload["method"], payload["data"])
                    self.store.execute("UPDATE outbox SET state='sent',payload_enc=? WHERE id=?", (self.store.vault.seal({}), row["id"]))
                    if payload.get("expire_after") and result and result.get("message_id"):
                        self.store.enqueue_outbox({"method": "deleteMessage", "data": {"chat_id": payload["data"]["chat_id"], "message_id": result["message_id"]}}, "delete:"+row["id"], now()+int(payload["expire_after"]))
                except Exception:
                    self.store.execute("UPDATE outbox SET state=?,due_at=? WHERE id=?", ("failed" if row["attempts"] >= 8 else "waiting", now()+min(300, 2**min(8, row["attempts"]+1)), row["id"]))
            await asyncio.sleep(1)


def embedded_assets() -> dict[str, tuple[bytes, str]]:
    if ASSET_BUNDLE.startswith("__"):
        return {}
    data = json.loads(zlib.decompress(base64.b85decode(ASSET_BUNDLE)))
    return {name: (base64.b64decode(item["data"]), item["type"]) for name, item in data.items()}


def qr_image(uri: str) -> str:
    try:
        import qrcode
        image = qrcode.make(uri)
        output = io.BytesIO()
        image.save(output, format="PNG")
        return "data:image/png;base64,"+base64.b64encode(output.getvalue()).decode()
    except ImportError:
        return ""


def topup_public(row: dict, with_qr: bool = False) -> dict:
    result = dict(row)
    result["rub_amount"] = rub(row["rub_kopeks"])
    result["uri"] = "litecoin:"+row["address"]+"?"+urllib.parse.urlencode({"amount": row["ltc_amount"], "label": "acczLOL", "message": "Deposit "+row["id"][:8]})
    if with_qr:
        result["qr"] = qr_image(result["uri"])
    return result


class WebService:
    def __init__(self, store: Store, settings: Settings, bot: TelegramAPI, prices: PriceFeed, assets: dict):
        self.store, self.settings, self.bot, self.prices, self.assets = store, settings, bot, prices, assets
        self.limiter = RateLimiter()

    def current_user(self, request: web.Request, required: bool = True) -> dict | None:
        header = request.headers.get("Authorization", "")
        token = header[7:] if header.startswith("Bearer ") else request.cookies.get("acczlol_session", "")
        user = self.store.session_user(token)
        if self.settings.demo and not user:
            user = self.store.one("SELECT * FROM users WHERE id=42")
        if not user and required:
            raise Fault("Войдите через Telegram или одноразовый код нашего бота", 401)
        return user

    def admin(self, request: web.Request) -> dict:
        user = self.current_user(request)
        if user["admin_until"] <= now():
            raise Fault("Требуется административный вход", 403)
        return user

    @staticmethod
    def json(data: Any, status: int = 200) -> web.Response:
        return web.json_response(data, status=status, dumps=lambda d: json.dumps(d, ensure_ascii=False, separators=(",", ":")))

    def cookie(self, response: web.Response, token: str):
        response.set_cookie("acczlol_session", token, max_age=self.settings.session_ttl, httponly=True,
            secure=self.settings.public_url.startswith("https://"), samesite="Lax", path="/")

    def profile(self, user: dict | None) -> dict | None:
        if not user:
            return None
        return {"id": user["id"], "name": user["name"], "username": user["username"], "balance": user["balance"],
            "balance_rub": rub(user["balance"]), "is_admin": user["admin_until"] > now(), "admin_until": user["admin_until"]}

    @web.middleware
    async def middleware(self, request: web.Request, handler: Callable):
        try:
            if request.path.startswith("/api/"):
                identity = self.current_user(request, required=False)
                peer = str(identity["id"]) if identity else (request.remote or "unknown")
                self.limiter.check("http:"+peer, 240, 60)
                if request.method not in ("GET", "HEAD", "OPTIONS"):
                    origin = request.headers.get("Origin", "")
                    target = self.settings.public_url or f"{request.scheme}://{request.host}"
                    expected = urllib.parse.urlsplit(target)
                    allowed = expected.scheme+"://"+expected.netloc
                    if origin != allowed:
                        raise Fault("Недопустимый источник запроса", 403)
            response = await handler(request)
        except Fault as error:
            response = self.json({"error": str(error), "status": error.status}, error.status)
        except web.HTTPException as error:
            response = error
        except Exception as error:
            LOG.error("HTTP handler failed: %s", type(error).__name__)
            response = self.json({"error": "Операция не выполнена. Повторите попытку или обратитесь в поддержку"}, 500)
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["Referrer-Policy"] = "no-referrer"
        response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
        if request.path.startswith("/api/") or request.path.startswith("/telegram/"):
            response.headers["Cache-Control"] = "private, no-store, max-age=0"
            response.headers["Pragma"] = "no-cache"
        response.headers["Content-Security-Policy"] = "default-src 'self'; script-src 'self' https://telegram.org; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; connect-src 'self'; media-src 'self' blob:; object-src 'none'; base-uri 'none'; frame-ancestors 'self' https://web.telegram.org https://*.telegram.org https://t.me"
        return response

    async def index(self, request: web.Request):
        body, mime = self.assets.get("index.html", (b"Build assets are missing", "text/plain"))
        return web.Response(body=body, content_type=mime, headers={"Cache-Control": "no-cache"})

    async def asset(self, request: web.Request):
        path = request.match_info["path"]
        item = self.assets.get(path)
        if not item:
            raise web.HTTPNotFound()
        etag = '"'+hashlib.sha256(item[0]).hexdigest()[:24]+'"'
        if request.headers.get("If-None-Match") == etag:
            return web.Response(status=304, headers={"ETag": etag})
        return web.Response(body=item[0], content_type=item[1], headers={"Cache-Control": "public, max-age=3600", "ETag": etag})

    async def health(self, request: web.Request):
        return self.json({"ok": True, "application": "acczLOL", "demo": self.settings.demo})

    async def webhook(self, request: web.Request):
        if not self.settings.webhook_secret or not hmac.compare_digest(request.headers.get("X-Telegram-Bot-Api-Secret-Token", ""), self.settings.webhook_secret):
            raise Fault("Нет доступа", 403)
        update = await request.json()
        try:
            await self.bot.handle_update(update, self.assets)
        except Fault as error:
            sender = update.get("message", {}).get("from", {}) or update.get("callback_query", {}).get("from", {})
            if sender.get("id"):
                self.store.enqueue_outbox({"method": "sendMessage", "data": {"chat_id": sender["id"], "text": str(error)}})
            self.store.execute("INSERT OR IGNORE INTO processed_updates VALUES(?,?)", (int(update["update_id"]), now()))
        return self.json({"ok": True})

    async def json_body(self, request: web.Request) -> dict:
        try:
            data = await request.json()
        except (ValueError, TypeError):
            raise Fault("Некорректный JSON") from None
        if not isinstance(data, dict):
            raise Fault("Ожидается объект JSON")
        return data

    async def api(self, request: web.Request):
        path, method = request.match_info["path"].strip("/"), request.method
        user = self.current_user(request, required=False)
        if path == "bootstrap" and method == "GET":
            return self.json({"brand": "acczLOL", "profile": self.profile(user), "demo": self.settings.demo,
                "bot_username": self.settings.bot_username, "emoji": EMOJI, "policy": self.store.policy(),
                "capabilities": {"bot": bool(self.settings.bot_token), "agent": bool(self.settings.api_id and self.settings.api_hash), "crypto_deposits": not self.settings.demo},
                "server_time": now()})
        if path == "auth/telegram" and method == "POST":
            data = await self.json_body(request)
            telegram_user = validate_init_data(str(data.get("init_data", "")), self.settings.bot_token)
            person = await asyncio.to_thread(self.store.user, telegram_user)
            token = self.store.make_session(person["id"])
            response = self.json({"profile": self.profile(person), "token": token})
            self.cookie(response, token)
            return response
        if path == "auth/code" and method == "POST":
            self.limiter.check("login:"+(request.remote or ""), 8, 900)
            data = await self.json_body(request)
            token = await asyncio.to_thread(self.store.redeem_login_code, str(data.get("code", "")))
            person = self.store.session_user(token)
            response = self.json({"profile": self.profile(person), "token": token})
            self.cookie(response, token)
            return response
        if path == "auth/logout" and method == "POST":
            token = request.cookies.get("acczlol_session", "") or request.headers.get("Authorization", "").removeprefix("Bearer ")
            self.store.execute("DELETE FROM web_sessions WHERE token_hash=?", (digest(token),))
            response = self.json({"ok": True})
            response.del_cookie("acczlol_session", path="/")
            return response
        if path == "catalog" and method == "GET":
            minimum = money_input(request.query.get("min", "0"), allow_zero=True)
            maximum = money_input(request.query.get("max", "1000000"))
            if maximum < minimum:
                raise Fault("Максимальная цена меньше минимальной")
            items = self.store.catalog(minimum, maximum, request.query.get("q", "")[:100])
            return self.json({"items": items, "total": len(items)})
        if path == "live" and method == "GET":
            stats = self.store.one("SELECT COUNT(*) total,SUM(kind='new') new,SUM(kind='warmed') warmed FROM accounts WHERE state='available'")
            return self.json({"stock": stats, "profile": self.profile(user), "server_time": now()})
        if path.startswith("emoji/") and method == "GET":
            emoji_id = path.split("/")[-1]
            if emoji_id not in EMOJI.values() or self.settings.demo:
                raise web.HTTPNotFound()
            item = await self.bot.emoji_asset(emoji_id)
            if not item:
                raise web.HTTPNotFound()
            return web.Response(body=item[0], content_type=item[1], headers={"Cache-Control": "public, max-age=3600"})
        user = self.current_user(request)
        if path == "profile" and method == "GET":
            return self.json({"profile": self.profile(user), "ledger": self.store.query("SELECT delta,kind,reference,created_at FROM ledger WHERE user_id=? ORDER BY id DESC LIMIT 100", (user["id"],))})
        if path == "admin/unlock" and method == "POST":
            self.limiter.check(f"admin:{user['id']}", 5, 900)
            data = await self.json_body(request)
            await asyncio.to_thread(self.store.unlock_admin, user["id"], str(data.get("key", "")))
            return self.json({"profile": self.profile(self.store.one("SELECT * FROM users WHERE id=?", (user["id"],)))})
        if path == "orders" and method == "GET":
            return self.json({"orders": self.store.order_rows(user["id"])})
        if path == "orders" and method == "POST":
            self.limiter.check(f"buy:{user['id']}", 20, 60)
            data = await self.json_body(request)
            order = await asyncio.to_thread(self.store.buy, user["id"], str(data.get("account_id", "")), str(data.get("request_key", "")))
            return self.json({"order": order, "balance_rub": rub(self.store.one("SELECT balance FROM users WHERE id=?", (user["id"],))["balance"])})
        if re.fullmatch(r"orders/[a-f0-9]{32}/access", path) and method == "POST":
            return self.json(self.store.access(user["id"], path.split("/")[1], user["admin_until"] > now()))
        if re.fullmatch(r"orders/[a-f0-9]{32}/code", path) and method == "POST":
            self.limiter.check(f"code:{user['id']}", 5, 60)
            return self.json({"job_id": self.store.request_code(user["id"], path.split("/")[1])})
        if re.fullmatch(r"jobs/[a-f0-9]{32}", path) and method == "GET":
            result = self.store.job_result(user["id"], path.split("/")[1], user["admin_until"] > now())
            result["error"] = ERROR_TEXT.get(result["error_code"], result["error_code"])
            return self.json(result)
        if path == "topups" and method == "GET":
            rows = self.store.query("SELECT * FROM topups WHERE user_id=? ORDER BY created_at DESC LIMIT 50", (user["id"],))
            return self.json({"items": [topup_public(row) for row in rows]})
        if path == "topups" and method == "POST":
            if self.settings.demo:
                raise Fault("В деморежиме настоящие пополнения отключены", 409)
            self.limiter.check(f"topup:{user['id']}", 5, 60)
            data = await self.json_body(request)
            amount = money_input(data.get("rub_amount", ""))
            rate, source = await self.prices.quote()
            row = self.store.create_topup(user["id"], amount, rate, source)
            return self.json(topup_public(row, with_qr=True))
        if re.fullmatch(r"topups/[a-f0-9]{32}", path) and method == "GET":
            row = self.store.one("SELECT * FROM topups WHERE id=? AND user_id=?", (path.split("/")[1], user["id"]))
            if not row:
                raise Fault("Заявка не найдена", 404)
            return self.json(topup_public(row, with_qr=True))
        if re.fullmatch(r"topups/[a-f0-9]{32}/submit", path) and method == "POST":
            data = await self.json_body(request)
            row = self.store.submit_topup(user["id"], path.split("/")[1], str(data.get("txid", "")))
            self.store.notify_admins(f"💸 Пополнение #{row['id'][:8]}\nПользователь: {user['id']}\nСумма: {rub(row['rub_kopeks'])} ₽\nLTC: {row['ltc_amount']}\nTXID: <code>{row['txid']}</code>\n\nПроверьте поступление и подтвердите в админ-панели.", event="topup-submit:"+row["id"])
            return self.json(topup_public(row))
        if path == "support" and method == "GET":
            return self.json(self.store.support_data(user["id"]))
        if path == "support" and method == "POST":
            self.limiter.check(f"support:{user['id']}", 20, 60)
            data = await self.json_body(request)
            ticket = self.store.support_send(user["id"], str(data.get("body", "")))
            return self.json({"ok": True, "ticket_id": ticket})
        if not path.startswith("admin/"):
            raise Fault("Маршрут не найден", 404)
        user = self.admin(request)
        if path == "admin/overview" and method == "GET":
            account_rows = self.store.query("SELECT id,title,username,price,kind,state,score,cover,login_enc,security_json,created_at,checked_at FROM accounts ORDER BY created_at DESC")
            for a in account_rows:
                a["login"] = self.store.vault.open(a.pop("login_enc")).get("login", "") if a["login_enc"] else ""
                a["security"] = json.loads(a.pop("security_json"))
                a["price_rub"] = rub(a["price"])
            orders = self.store.order_rows()
            topups = self.store.query("SELECT t.*,u.name,u.username FROM topups t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 200")
            jobs = self.store.query("SELECT id,kind,account_id,order_id,state,stage,attempts,error_code,created_at,updated_at FROM jobs ORDER BY created_at DESC LIMIT 100")
            return self.json({"accounts": account_rows, "orders": orders, "topups": [topup_public(r) for r in topups], "jobs": jobs,
                "users": self.store.query("SELECT id,name,username,balance,admin_until,created_at FROM users ORDER BY created_at DESC LIMIT 500"),
                "audit": self.store.query("SELECT * FROM audit ORDER BY id DESC LIMIT 100"), "policy": self.store.policy(),
                "agent_configured": bool(self.settings.api_id and self.settings.api_hash), "demo": self.settings.demo})
        if path == "admin/accounts" and method == "POST":
            if request.content_type == "multipart/form-data":
                reader = await request.multipart()
                fields: dict[str, Any] = {}
                while part := await reader.next():
                    data = await part.read(decode=False)
                    if len(data) > 5_000_000:
                        raise Fault("Файл слишком большой", 413)
                    fields[part.name] = bytes(data) if part.name == "session_file" else data.decode("utf-8")
            else:
                fields = await self.json_body(request)
            raw = fields.get("session_file") or fields.get("session", "")
            session = normalize_session(raw)
            account_id = self.store.add_account(user["id"], str(fields.get("title", "")), money_input(fields.get("price", "")), session, str(fields.get("password", "")), str(fields.get("kind", "new")))
            return self.json({"ok": True, "account_id": account_id})
        if path == "admin/import" and method == "POST":
            data = await self.json_body(request)
            content = str(data.get("content", "")).lstrip("\ufeff")
            if len(content.encode()) > 5_000_000:
                raise Fault("Файл слишком большой", 413)
            try:
                if str(data.get("filename", "")).lower().endswith(".csv"):
                    delimiter = ";" if ";" in content.split("\n", 1)[0] else ","
                    rows = list(csv.DictReader(io.StringIO(content), delimiter=delimiter))
                else:
                    rows = json.loads(content)
                if not isinstance(rows, list) or not 1 <= len(rows) <= 100:
                    raise Fault("Нужен массив от 1 до 100 записей")
                normalized = []
                for row in rows:
                    if not isinstance(row, dict):
                        raise Fault("Каждая запись должна быть объектом")
                    normalized.append({"title": str(row.get("title", "Telegram аккаунт"))[:100],
                        "price": money_input(row.get("price", "")), "kind": "warmed" if row.get("kind") == "warmed" else "new",
                        "session": normalize_session(str(row.get("session", ""))), "password": str(row.get("password", ""))})
            except (ValueError, csv.Error):
                raise Fault("Проверьте JSON/CSV и обязательные поля") from None
            with self.store.transaction() as db:
                for row in normalized:
                    account_id = uid()
                    db.execute("INSERT INTO accounts(id,title,price,kind,secret_enc,created_at) VALUES(?,?,?,?,?,?)", (account_id, row["title"], row["price"], row["kind"], self.store.vault.seal({"session": row["session"], "password": row["password"]}), now()))
                    self.store._job(db, self.store.vault, "validate", account_id)
                self.store.audit(db, user["id"], "Импорт аккаунтов", str(len(normalized)))
            return self.json({"ok": True, "count": len(normalized)})
        if re.fullmatch(r"admin/accounts/[a-f0-9]{32}/recheck", path) and method == "POST":
            return self.json({"job_id": self.store.recheck(user["id"], path.split("/")[2])})
        if re.fullmatch(r"admin/accounts/[a-f0-9]{32}/edit", path) and method == "POST":
            data = await self.json_body(request)
            account_id = path.split("/")[2]
            title, amount = str(data.get("title", ""))[:100], money_input(data.get("price", ""))
            with self.store.transaction() as db:
                row = db.execute("SELECT state FROM accounts WHERE id=?", (account_id,)).fetchone()
                if not row or row["state"] in ("sold", "reserved"):
                    raise Fault("Нельзя изменить уже купленный или зарезервированный аккаунт", 409)
                db.execute("UPDATE accounts SET title=?,price=?,kind=? WHERE id=?", (title or "Telegram аккаунт", amount, "warmed" if data.get("kind") == "warmed" else "new", account_id))
                self.store.audit(db, user["id"], "Изменены метаданные аккаунта", account_id)
            return self.json({"ok": True})
        if re.fullmatch(r"admin/topups/[a-f0-9]{32}/review", path) and method == "POST":
            data = await self.json_body(request)
            if data.get("approve") is True and data.get("verified") is not True:
                raise Fault("Подтвердите, что вручную проверили поступление Litecoin")
            return self.json(topup_public(self.store.review_topup(user["id"], path.split("/")[2], data.get("approve") is True, str(data.get("note", "")))))
        if re.fullmatch(r"admin/orders/[a-f0-9]{32}/refund", path) and method == "POST":
            data = await self.json_body(request)
            self.store.refund(user["id"], path.split("/")[2], str(data.get("reason", "ADMIN_REFUND")))
            return self.json({"ok": True})
        if path == "admin/support" and method == "GET":
            return self.json(self.store.support_data(ticket_id=request.query.get("ticket")))
        if path == "admin/support/reply" and method == "POST":
            data = await self.json_body(request)
            self.store.support_reply(user["id"], str(data.get("ticket_id", "")), str(data.get("body", "")))
            return self.json({"ok": True})
        if path == "admin/settings" and method == "POST":
            data = await self.json_body(request)
            return self.json(self.store.save_policy(user["id"], data))
        raise Fault("Маршрут не найден", 404)

    def app(self) -> web.Application:
        app = web.Application(middlewares=[self.middleware], client_max_size=6_000_000)
        app.router.add_get("/", self.index)
        app.router.add_get("/healthz", self.health)
        app.router.add_get("/assets/{path:.*}", self.asset)
        app.router.add_get("/images/{path:.*}", self.image_alias)
        app.router.add_route("*", "/api/{path:.*}", self.api)
        app.router.add_post("/telegram/webhook", self.webhook)
        return app

    async def image_alias(self, request: web.Request):
        item = self.assets.get("images/"+request.match_info["path"])
        if not item:
            raise web.HTTPNotFound()
        return web.Response(body=item[0], content_type=item[1], headers={"Cache-Control": "public, max-age=3600"})


